"""Load all submodules in this module.

Taken from https://stackoverflow.com/a/3365846/4330447.
"""

import importlib
import pkgutil

__all__ = []
for loader, module_name, is_pkg in pkgutil.walk_packages(__path__):
  # We need to exclude modules ending with '_bootstrap' because those are
  # generated by py_binary. We also exclude '_test' modules.
  if module_name.endswith('_bootstrap') or module_name.endswith('_test'):
    continue
  __all__.append(module_name)
  _module = importlib.import_module(f'.{module_name}', 'derived_metadata')
  globals()[module_name] = _module
